 actors={PlacedPiece{0,0,8,8,3},PlacedPiece{0,0,8,8,0x8004}};check(scene.render(actors,kSceneRGB888,image,e)&&image.indexed[0]==1,"earlier low sprite owns pixel before high sprite then plane priority");
