int main(int argc,char**argv){runSceneRendererTests();if(argc==1)return 0;if(argc==3&&std::string(argv[1])=="--allocations"){std::ifstream manifest(argv[2]);std::string path;unsigned index;size_t entries=0,accepted=0,rejected=0;while(manifest>>path>>index){std::vector<uint8_t> resource=bytes(path.c_str());std::string error;Snatcher::SceneAssets assets;Snatcher::SceneRenderer renderer;bool ok=Snatcher::parseSceneAssets(resource.data(),resource.size(),index,4*1024*1024,assets,error)==Snatcher::kSceneAssetsReady;for(size_t i=0;ok&&i<assets.transfers.size();++i)ok=renderer.applyTransfer(assets.transfers[i],error);++entries;if(ok)++accepted;else++rejected;}std::printf("scene allocation corpus: %zu entries, %zu accepted, %zu rejected\n",entries,accepted,rejected);return manifest.bad()?3:0;}if((argc!=12&&argc!=13)||std::string(argv[1])!="--fixture")return 2;using namespace Snatcher;std::vector<uint8_t> resource=bytes(argv[2]),pal=bytes(argv[4]);if(pal.size()!=128)return 2;std::string error;SceneAssets assets;if(parseSceneAssets(resource.data(),resource.size(),unsigned(std::stoul(argv[3])),4*1024*1024,assets,error)!=kSceneAssetsReady)return 3;SceneRenderer renderer;SceneLayout layout;layout.width=256;layout.height=224;layout.columns=std::stoul(argv[5]);layout.rows=std::stoul(argv[6]);layout.sourceX[0]=std::stoi(argv[7]);layout.sourceY[0]=std::stoi(argv[8]);layout.sourceX[1]=std::stoi(argv[9]);layout.sourceY[1]=std::stoi(argv[10]);if(!renderer.configure(layout,error))return 3;if(!renderer.establishSceneReset(layout.columns==64&&layout.rows==64?kSceneSquareLayout:layout.columns==32?kSceneTallLayout:kSceneWideLayout,error))return 3;for(const GraphicsTransfer&t:assets.transfers)if(!renderer.applyTransfer(t,error)){std::fprintf(stderr,"%s\n",error.c_str());return 3;}std::vector<uint16_t> palette;for(size_t i=0;i<128;i+=2)palette.push_back(uint16_t(uint16_t(pal[i])<<8|pal[i+1]));SceneGraphicsQueue graphics;for(const GraphicsTransfer&transfer:assets.transfers)if(!graphics.setStaging(0,transfer.decoded,error))return 3;std::vector<PlacedPiece> drawList;if(argc==13){std::ifstream input(argv[12]);std::string kind;while(input>>kind){if(kind=="fill"){unsigned plane,column,row,columns,rows,attribute;if(!(input>>plane>>column>>row>>columns>>rows>>attribute)||!renderer.fillPlaneCells(plane,column,row,columns,rows,uint16_t(attribute),error))return 3;}else if(kind=="task"){unsigned offset;if(!(input>>offset))return 3;SceneGraphicsTask task;if(!readSceneGraphicsTask(resource.data(),resource.size(),offset,0x28000,task,error))return 3;if(!graphics.enqueue(task,error))return 3;std::vector<GraphicsTransfer> ready;if(!graphics.tick(false,ready,error))return 3;for(const GraphicsTransfer&transfer:ready)if(!renderer.applyTransfer(transfer,error))return 3;}else if(kind=="actor"){unsigned table,frame,style,paletteOverride;int x,y;if(!(input>>table>>frame>>x>>y>>style>>paletteOverride))return 3;std::vector<FramePiece> geometry;std::vector<PlacedPiece> placed;FramePlacement placement;placement.x=x;placement.y=y;placement.flipX=(style&1)!=0;placement.flipY=(style&2)!=0;placement.overridePalette=(paletteOverride&128)!=0;placement.palette=paletteOverride&3;if(!readFrameGeometry(resource.data(),resource.size(),table,frame,4096,geometry,error)||!placeFrame(geometry,placement,4096,placed,error))return 3;drawList.insert(drawList.end(),placed.begin(),placed.end());}else return 3;}if(input.bad())return 3;}
 SceneImage image;if(!renderer.setPalette(palette,0,error)||!renderer.render(drawList,kSceneReferenceRGB565,image,error)){std::fprintf(stderr,"%s\n",error.c_str());return 3;}std::ofstream out(argv[11],std::ios::binary);out.write(reinterpret_cast<const char*>(image.rgb.data()),image.rgb.size());return out?0:4;}
